package org.sangam.core.power;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;

/**
 * {@link OperationMetadata} from the deployed pack manifest (owner decision 193): whether an operation is monetary, its
 * currency and its limit-table key are declared per action in the manifest's {@code powers} block, generated by packgen
 * and versioned with the pack. The host supplies the deployment of the stored case type and version
 * ({@link Deployments}); nothing in a request, process variable or pack input is read. The metadata version recorded
 * in every decision is {@code pack:<id>@<version>}.
 *
 * <p>The {@code powers} block ({@link #parse}), one entry per action:
 * <pre>
 * "powers": {
 *   "SANCTION": {"monetary": true, "currency": "INR", "limitTable": "dop-sanction", "ruleCaseType": "GRANT"},
 *   "DISPOSE":  {"monetary": false, "limitTable": "dop-disposal"}
 * }
 * </pre>
 * {@code ruleCaseType} (optional, owner decision 222) is the case type the delegation table is consulted with; the
 * evaluator's rule inputs take it only from here ({@link Classification#ruleInputs}), never from a start variable.
 * Parsing is strict: an unknown key, a value of the wrong type, a currency on a non-monetary action or a missing one
 * on a monetary action is refused, so a malformed manifest never yields a permissive classification.
 */
public final class ManifestOperationMetadata implements OperationMetadata {

    /**
     * The manifest declaration of one action.
     *
     * @param ruleCaseType the delegation table's case type (decision 222), null when the manifest declares none
     */
    public record Declaration(boolean monetary, String currency, String limitTableKey, String ruleCaseType) {

        /** A declaration without a rule case type. */
        public Declaration(boolean monetary, String currency, String limitTableKey) {
            this(monetary, currency, limitTableKey, null);
        }

        public Declaration {
            // the same rules as a classification; the version is checked when one is built
            new Classification(monetary, currency, limitTableKey, "check", ruleCaseType);
        }
    }

    /** One deployed pack version and the declarations of the case type it deploys. */
    public record Deployed(String packId, String packVersion, Map<String, Declaration> actions) {
        public Deployed {
            if (packId == null || packId.isBlank() || packVersion == null || packVersion.isBlank()) {
                throw new IllegalArgumentException("a deployed manifest names its pack id and version");
            }
            actions = Map.copyOf(Objects.requireNonNull(actions, "actions"));
        }

        /** The metadata version recorded in decisions and audit. */
        public String metadataVersion() {
            return "pack:" + packId + "@" + packVersion;
        }
    }

    /** The host's lookup of the deployment that defines a stored case type and version in a tenant. */
    @FunctionalInterface
    public interface Deployments {
        Optional<Deployed> deployed(String tenant, String caseType, int caseTypeVersion);
    }

    private static final Set<String> KEYS = Set.of("monetary", "currency", "limitTable", "ruleCaseType");

    private final Deployments deployments;

    public ManifestOperationMetadata(Deployments deployments) {
        this.deployments = Objects.requireNonNull(deployments, "deployments");
    }

    @Override
    public Optional<Classification> classify(String tenant, String caseType, int caseTypeVersion, String action) {
        if (tenant == null || caseType == null || action == null) {
            return Optional.empty();
        }
        Optional<Deployed> d = deployments.deployed(tenant, caseType, caseTypeVersion);
        if (d == null || d.isEmpty()) {
            return Optional.empty();
        }
        Declaration decl = d.get().actions().get(action);
        if (decl == null) {
            return Optional.empty();
        }
        return Optional.of(new Classification(decl.monetary(), decl.currency(), decl.limitTableKey(),
                d.get().metadataVersion(), decl.ruleCaseType()));
    }

    /**
     * Reads a manifest {@code powers} block (a JSON object read as a map).
     *
     * @throws IllegalArgumentException on anything but the documented shape
     */
    public static Map<String, Declaration> parse(Object powers) {
        if (powers == null) {
            return Map.of();
        }
        if (!(powers instanceof Map<?, ?> block)) {
            throw new IllegalArgumentException("powers must be an object");
        }
        Map<String, Declaration> out = new LinkedHashMap<>();
        for (Map.Entry<?, ?> e : block.entrySet()) {
            if (!(e.getKey() instanceof String action) || action.isBlank()) {
                throw new IllegalArgumentException("a powers entry needs an action name");
            }
            if (!(e.getValue() instanceof Map<?, ?> m)) {
                throw new IllegalArgumentException("powers." + action + " must be an object");
            }
            for (Object k : m.keySet()) {
                if (!KEYS.contains(k)) {
                    throw new IllegalArgumentException("powers." + action + " has an unknown key " + k);
                }
            }
            if (!(m.get("monetary") instanceof Boolean monetary)) {
                throw new IllegalArgumentException("powers." + action + ".monetary must be true or false");
            }
            Object currency = m.get("currency");
            if (currency != null && !(currency instanceof String)) {
                throw new IllegalArgumentException("powers." + action + ".currency must be a string");
            }
            if (!(m.get("limitTable") instanceof String table)) {
                throw new IllegalArgumentException("powers." + action + ".limitTable must be a string");
            }
            Object ruleCaseType = m.get("ruleCaseType");
            if (m.containsKey("ruleCaseType") && !(ruleCaseType instanceof String s && !s.isBlank())) {
                throw new IllegalArgumentException("powers." + action + ".ruleCaseType must be a non-blank string");
            }
            try {
                out.put(action, new Declaration(monetary, (String) currency, table, (String) ruleCaseType));
            } catch (IllegalArgumentException bad) {
                throw new IllegalArgumentException("powers." + action + ": " + bad.getMessage(), bad);
            }
        }
        return Map.copyOf(out);
    }
}
